// Files that hand the documentation to language models and coding agents (docs/ai.md):
//   /llms.txt, /de/llms.txt              index of every page (llmstxt.org format)
//   /llms-full.txt, /de/llms-full.txt    every page's Markdown in one file
//   /downloads/strido-skill.zip         an Agent Skill: skills/strido/SKILL.md + references/ (all pages, both languages)
// Generated by the docs sync from the same pages the site publishes; the assistant service serves
// them to bearer-token clients under /api/agent/.
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { zipArchive } from './build-kit.mjs';
import { SITE_URL, repositoryRoot } from './pages.mjs';

export const SKILL_NAME = 'strido-skill.zip';
const SKILL_SOURCE = 'skills/strido/SKILL.md';
const INTRO = {
  en: 'Strido is an open 12-DoF quadruped robot: printable CAD, a verified assembly, parts catalogue and shop, electronics and wiring, ESP32-S3 firmware, ROS 2, simulation and reinforcement learning, and an engineering wiki.',
  de: 'Strido ist ein offener Vierbeiner-Roboter mit 12 Freiheitsgraden: druckbares CAD, geprüfte Montage, Teilekatalog und Shop, Elektronik und Verkabelung, ESP32-S3-Firmware, ROS 2, Simulation und Reinforcement Learning sowie ein Technik-Wiki.',
};

function forAgents(markdown) {
  // Drop front matter and lines that are only a site component (<PartsShop />, <TranslationNotice ... />).
  return markdown
    .replace(/^---\n[\s\S]*?\n---\n/, '') // YAML front matter at the top
    .replace(/^\s*<\/?[A-Z][A-Za-z]*\b[^>]*>\s*$/gm, '') // a line holding only a Vue component tag
    .replace(/\n{3,}/g, '\n\n') // collapse the blank lines left behind
    .trim();
}

function urlOf(route) {
  return `${SITE_URL}${route}`;
}

function llmsIndex(locale, sidebar, pages) {
  // llms.txt: title, summary, then one list per sidebar section.
  const prefix = locale === 'en' ? '' : `/${locale}`;
  const sections = [...(sidebar[`${prefix}/`] ?? []), ...(sidebar[`${prefix}/docs/wiki/`] ?? [])];
  const lines = [`# Strido${locale === 'de' ? ' (Deutsch)' : ''}`, '', `> ${INTRO[locale]}`, '',
    `Full text: ${urlOf(`${prefix}/llms-full.txt`)}. MCP server: ${urlOf('/mcp')} (tools search_docs, read_page, list_pages, search_parts). Agent Skill: ${urlOf(`/downloads/${SKILL_NAME}`)}.`, ''];
  const seen = new Set();
  for (const section of sections) {
    const items = (section.items ?? []).filter((item) => item.link && !seen.has(item.link) && pages.has(item.link));
    if (!items.length) continue;
    lines.push(`## ${section.text}`, '');
    for (const item of items) {
      seen.add(item.link);
      lines.push(`- [${item.text}](${urlOf(item.link)})`);
    }
    lines.push('');
  }
  return lines.join('\n');
}

function llmsFull(locale, pages) {
  const parts = [`# Strido — ${locale === 'de' ? 'vollständige Dokumentation' : 'complete documentation'}`, '', `> ${INTRO[locale]}`, ''];
  for (const [route, page] of pages) parts.push(`<!-- ${urlOf(route)} -->`, '', forAgents(page.text), '', '---', '');
  return parts.join('\n');
}

export async function agentFiles(languages, sidebar) {
  // languages: {en: [{route, relative (English content path), title, text}], de: [...]} -> {public path: Buffer}
  const files = {};
  const skill = [['strido/SKILL.md', await readFile(path.join(repositoryRoot, SKILL_SOURCE))]];
  const index = ['# Strido references', '', 'Every page of the documentation site as Markdown. English under `en/`, German under `de/`.', ''];
  for (const [locale, list] of Object.entries(languages)) {
    const prefix = locale === 'en' ? '' : `${locale}/`;
    const pages = new Map(list.map((page) => [page.route, page]));
    files[`${prefix}llms.txt`] = Buffer.from(llmsIndex(locale, sidebar, pages));
    files[`${prefix}llms-full.txt`] = Buffer.from(llmsFull(locale, pages));
    index.push(`## ${locale === 'en' ? 'English' : 'Deutsch'}`, '');
    for (const page of list) {
      const reference = `references/${locale}/${page.relative}`;
      skill.push([`strido/${reference}`, Buffer.from(`<!-- ${urlOf(page.route)} -->\n\n${forAgents(page.text)}\n`)]);
      index.push(`- [${page.title}](${reference.replace(/^references\//, '')}) — ${urlOf(page.route)}`);
    }
    index.push('');
  }
  skill.push(['strido/references/README.md', Buffer.from(index.join('\n'))]);
  files[`downloads/${SKILL_NAME}`] = zipArchive(skill.sort(([a], [b]) => (a === 'strido/SKILL.md' ? -1 : b === 'strido/SKILL.md' ? 1 : a.localeCompare(b)))).zip;
  return files;
}
